import{Rt as e,Vt as t,Z as n,_t as r,at as i,et as a,nt as o,p as s,rt as c,yt as l}from"./chunks/framework.Bcve9O8f.js";import{o as u}from"./chunks/theme.DoN31B1h.js";var d={style:{margin:`.3rem 0`}},f=[`href`],p={key:0},m=JSON.parse(`{"title":"Nature, proved","description":"Where the deposit's proved laws meet nature and daily life — each labelled a fact of nature, a practice, or a metaphor, and linked to its theorem.","frontmatter":{"title":"Nature, proved","description":"Where the deposit's proved laws meet nature and daily life — each labelled a fact of nature, a practice, or a metaphor, and linked to its theorem.","head":[["meta",{"name":"robots","content":"index, follow"}],["meta",{"property":"og:title","content":"Nature, proved | Millennium Solutions"}],["meta",{"property":"og:description","content":"Where the deposit's proved laws meet nature and daily life — each labelled a fact of nature, a practice, or a metaphor, and linked to its theorem."}],["meta",{"property":"og:url","content":"https://ceccec.psg.bg/millennium-solutions/nature.html"}],["meta",{"property":"og:locale","content":"en_US"}],["meta",{"name":"twitter:title","content":"Nature, proved | Millennium Solutions"}],["meta",{"name":"twitter:description","content":"Where the deposit's proved laws meet nature and daily life — each labelled a fact of nature, a practice, or a metaphor, and linked to its theorem."}],["link",{"rel":"canonical","href":"https://ceccec.psg.bg/millennium-solutions/nature.html"}],["link",{"rel":"alternate","hreflang":"en","href":"https://ceccec.psg.bg/millennium-solutions/nature.html"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://ceccec.psg.bg/millennium-solutions/nature.html"}]]},"headers":[],"relativePath":"nature.md","filePath":"nature.md"}`),h=Object.assign({name:`nature.md`},{setup(m){let h=new Map(u.filter(e=>!e.revoked).map(e=>[e.key,e])),g=[{kind:`fact`,where:`Sunflowers, pinecones, pineapples`,what:`The spiral counts on a seed head are usually two consecutive Fibonacci numbers — 34 and 55, 55 and 89. Consecutive Fibonacci numbers share no common divisor but 1, at every size, so the two families of spirals never fall into a common sub-rhythm.`,keys:[`lean_z9plus_consecutive_fibonacci_are_coprime_for_every_n`,`lean_families_cassinis_identity_for_every_m`]},{kind:`fact`,where:`Leaves around a stem`,what:`Ratios of neighbouring Fibonacci numbers close in on the golden ratio — each convergent off by exactly one unit in the determinant — the spacing (about 137.5° between leaves) that many plants use to keep leaves from shading each other.`,keys:[`lean_families_the_golden_convergents_are_fibonacci_ratios_with_unit_determinant`,`lean_elementary_the_lucas_numbers_are_the_sum_of_the_neighbouring_fibonaccis_for_every_n`]},{kind:`fact`,where:`Honeycomb`,what:`Six turns of 60° close the circle, so hexagons tile a flat surface; among all tilings into equal cells, the hexagonal one uses the least wall for the area enclosed (the honeycomb theorem, Thomas Hales, 1999 — prior art, not proved here).`,keys:[`lean_mechanical_the_regular_hexagon_exterior_angle_is_the_gold_string`]},{kind:`fact`,where:`Islands, cups, cells — every surface`,what:`χ = 2 − 2g for a surface with g holes: a sphere 2, a doughnut 0, a pretzel of two holes −2. Counting holes tells shapes apart that no stretching can turn into one another.`,keys:[`lean_demand3_the_euler_characteristic_of_a_genus_g_surface_for_every_g`]},{kind:`fact`,where:`Water and energy`,what:`Mass is conserved at every scale, so no closed loop makes water from nothing: every atom that comes out went in. A device that promises more out than in is refuted before it is built.`,keys:[`lean_energy_mass_is_conserved_at_every_scale_so_the_loop_cannot_make_water`]},{kind:`fact`,where:`Your family tree`,what:`Going back, ancestors double each generation: 1 + 2 + 4 + … + 2ⁿ = 2ⁿ⁺¹ − 1. Within a few dozen generations that exceeds everyone who has ever lived, so the branches must meet — we are all related.`,keys:[`lean_families_the_powers_of_two_sum_to_one_less_than_the_next_for_every_n`]},{kind:`fact`,where:`An honest second`,what:`The second reads back exactly from the metre and from the caesium period, for every whole number of seconds — the same measure for everyone, everywhere.`,keys:[`lean_light_the_second_returns_from_the_metre_and_the_period_at_every_duration`]},{kind:`practice`,where:`A right angle with a rope`,what:`Knot a loop of rope into 12 equal parts and peg it as 3, 4 and 5: the corner is square. It works at any size (every multiple of 3-4-5), for fields, garden beds and walls, with no instrument.`,keys:[`lean_mechanical_every_multiple_of_three_four_five_is_pythagorean`]},{kind:`practice`,where:`Planting in rows`,what:`Rows of 1, 2, 3, … n plants need n(n + 1)/2 seedlings in all; a square bed grows by one L-shaped border of the next odd number of plants.`,keys:[`lean_families_the_numbers_sum_to_their_closed_form_for_every_n`,`lean_families_the_first_n_odd_numbers_sum_to_n_squared_for_every_n`]},{kind:`practice`,where:`Stacking fruit`,what:`A pile of oranges in triangular layers holds a tetrahedral number: the sum of the triangular numbers, n(n + 1)(n + 2)/6.`,keys:[`lean_families_the_sums_of_triangular_numbers_are_the_tetrahedral_numbers_for_every_n`]},{kind:`practice`,where:`Checking a bill by hand`,what:`Casting out nines: the digit root of a product is the digit root of the product of the roots, for every pair of numbers — a check at the market with no calculator. Its frontier is honest too: a number and its reversal keep the same remainder by nine, so swapped digits slip through; that is why bank and book numbers use weighted checks (mod 97, mod 11).`,keys:[`lean_mechanical_casting_out_nines_is_multiplicative_for_every_a_b`,`lean_reversal_reversal_keeps_the_residue_mod_nine_for_every_n`]},{kind:`practice`,where:`Taking turns fairly`,what:`A B B A B A A B … — the Thue–Morse order — shares first-mover advantage more fairly than A B A B, when children pick teams or neighbours share a well.`,keys:[`lean_sequences_thue_morse_doubling_recurrence`,`lean_sequences_thue_morse_doubling_recurrence_for_every_n`]},{kind:`practice`,where:`A fair price`,what:`The deposit’s fare is two coins, fixed by a theorem rather than by whoever holds power: 110 − 108 = 2 = −χ at genus 2.`,keys:[`lean_demand3_the_two_coin_fare_is_minus_the_euler_characteristic_at_genus_two`]},{kind:`metaphor`,where:`Repair`,what:`Every step of XOR is undone by repeating it: (a ⊕ b) ⊕ b = a, for every a and b. A picture of repair — a metaphor, not a law of people.`,keys:[`lean_nim_xor_is_its_own_inverse_for_every_a_b`]},{kind:`metaphor`,where:`Rhythm`,what:`The Fibonacci numbers repeat their remainders by nine every 24 steps, forever. An arithmetic rhythm — not a claim about days or bodies.`,keys:[`lean_z9plus_pisano_period_mod_nine_is_twenty_four_for_every_k`]},{kind:`metaphor`,where:`Colour`,what:`Nine digits at 40° each close the colour wheel with nine distinct hues. A design mapping, honestly labelled.`,keys:[`lean_mechanical_arts_nine_hues_distinct`]}],_={fact:`Facts of nature`,practice:`Practices you can use`,metaphor:`Metaphors, labelled as such`},v=g.map(e=>({...e,proofs:e.keys.filter(e=>h.has(e)).map(e=>({key:e,name:h.get(e).name.split(`—`)[0].trim()}))})).filter(e=>e.proofs.length),y=Object.entries(_).map(([e,t])=>({k:e,title:t,items:v.filter(t=>t.kind===e)})).filter(e=>e.items.length);return(u,m)=>(r(),c(`div`,null,[m[2]||=a(`h1`,{id:`nature-proved`,tabindex:`-1`},[i(`Nature, proved `),a(`a`,{class:`header-anchor`,href:`#nature-proved`,"aria-label":`Permalink to “Nature, proved”`},`​`)],-1),m[3]||=a(`blockquote`,null,[a(`p`,null,`Mathematics does not make a life blissful. What it can do is show the order in what we already see, let anyone check a claim for themselves, and remove the fear of being cheated — so attention is free for the garden, the people, the light. Each entry below links to the theorem the Lean kernel checked, for every value.`)],-1),a(`p`,null,[a(`strong`,null,t(e(v).length),1),m[0]||=i(` places where a proved law meets nature or daily life, drawn live from the ledger — an entry disappears if its theorem is ever withdrawn.`,-1)]),(r(!0),c(n,null,l(e(y),u=>(r(),c(n,{key:u.k},[a(`h2`,null,t(u.title),1),(r(!0),c(n,null,l(u.items,u=>(r(),c(`div`,{key:u.where,style:{border:`1px solid var(--vp-c-divider)`,"border-radius":`10px`,padding:`.6rem 1rem`,margin:`.8rem 0`}},[a(`strong`,null,t(u.where),1),a(`p`,d,t(u.what),1),a(`small`,null,[m[1]||=i(`Proved: `,-1),(r(!0),c(n,null,l(u.proofs,(i,l)=>(r(),c(n,{key:i.key},[a(`a`,{href:e(s)(`/theorem/`+i.key)},t(i.name),9,f),l<u.proofs.length-1?(r(),c(`span`,p,` · `)):o(``,!0)],64))),128))])]))),128))],64))),128)),m[4]||=a(`h2`,{id:`the-frontier-and-where-it-leads`,tabindex:`-1`},[i(`The frontier, and where it leads `),a(`a`,{class:`header-anchor`,href:`#the-frontier-and-where-it-leads`,"aria-label":`Permalink to “The frontier, and where it leads”`},`​`)],-1),m[5]||=a(`p`,null,`The laws here are classical — Fibonacci, Pythagoras, Euler, Thue and Morse long before this deposit. What is new is only that each is checked by the kernel for every value, where before it was checked up to a bound. That frontier leads outward: a law anyone can recompute on a phone is a law no one can use to cheat them — in a market, a land record, a water promise. The bliss is not in the proof; the proof clears the way to it.`,-1)]))}});export{m as __pageData,h as default};